SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ----------------------------
-- Table structure for license
-- ----------------------------
DROP TABLE IF EXISTS `license`;
CREATE TABLE `license` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `license_id` varchar(255) COLLATE utf8mb4_bin DEFAULT '' COMMENT '许可证id',
  `license_name` varchar(255) COLLATE utf8mb4_bin DEFAULT '' COMMENT '许可证名称',
  `license_url` text COLLATE utf8mb4_bin COMMENT '许可证地址',
  `is_custom_license` tinyint(3) DEFAULT '0' COMMENT '是否是自定义许可证 1是 0否',
  `is_deprecated` tinyint(3) DEFAULT '0' COMMENT '是否已弃用 1是 0否',
  `is_osi_approved` tinyint(3) DEFAULT '0' COMMENT '是否属于OSI-Approved授权协议 1是 0否',
  `is_fsf_libre` tinyint(3) DEFAULT '0' COMMENT '是否为自由软件基金会 1是 0否',
  `header` text COLLATE utf8mb4_bin COMMENT '许可证头信息',
  `template` text COLLATE utf8mb4_bin COMMENT '许可证模板',
  `content` text COLLATE utf8mb4_bin COMMENT '许可证原文内容',
  `content_cn` text COLLATE utf8mb4_bin COMMENT '许可证中文内容',
  `comment` text COLLATE utf8mb4_bin COMMENT '备注',
  PRIMARY KEY (`id`),
  KEY `idx_license_id` (`license_id`) USING BTREE,
  KEY `idx_license_name` (`license_name`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=490 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='许可证';

